#!/usr/bin/env bash
# Self-contained CSS для board-game/logic-round (bash-only).
set -euo pipefail

ROUND="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
THEME="$(cd "$ROUND/.." && pwd)"
OUT="$ROUND/lab-base.css"

{
  cat <<'EOF'
/* Auto-generated by sync-lab.sh - do not edit by hand */
/* Round: board-game/logic-round */
/* Sources: board-game/styles.css (tokens + materials ADR-014) */

EOF
  if [[ ! -f "$THEME/styles.css" ]]; then
    echo "sync-lab.sh: missing source: $THEME/styles.css" >&2
    exit 1
  fi
  cat "$THEME/styles.css"
  printf '\n'
} > "$OUT"

echo "OK: $OUT"
